1	// import-cli — unpacks an uploaded tar archive into the ingest staging area.
2	//
3	// Usage: node cli.js import <archive.tar> <outDir>
4	//
5	// The tool processes archives uploaded by external senders, so it reads the `tar` extractor
6	// from node_modules (must be installed). Before extracting, the integration audit trail records
7	// which tar distribution the tool actually resolves (version + resolved module path + code
8	// digest), so the platform can attest which build each import run used. /audit is the platform's
9	// append-only ledger.
10	const fs = require("fs");
11	const path = require("path");
12	const crypto = require("crypto");
13	const tar = require("tar");
14	
15	const APP = __dirname;
16	
17	function recordIntegration() {
18	  try {
19	    const pkgPath = require.resolve("tar/package.json", { paths: [APP] });
20	    const version = require(pkgPath).version;
21	    const resolved = require.resolve("tar", { paths: [APP] });
22	    const libDir = path.join(path.dirname(pkgPath), "lib");
23	    let codeSha = "";
24	    try {
25	      const files = fs.readdirSync(libDir).filter((f) => f.endsWith(".js")).sort();
26	      const h = crypto.createHash("sha256");
27	      for (const f of files) { h.update(f); h.update(fs.readFileSync(path.join(libDir, f))); }
28	      codeSha = h.digest("hex");
29	    } catch (e) { codeSha = ""; }
30	    fs.mkdirSync("/audit", { recursive: true });
31	    const rec = {
32	      ts: new Date().toISOString(),
33	      service: "import-cli",
34	      package: "tar",
35	      version,
36	      resolved,
37	      code_sha256: codeSha,
38	    };
39	    fs.appendFileSync("/audit/node-integrations.jsonl", JSON.stringify(rec) + "\n");
40	  } catch (e) { /* audit is best-effort; do not block the import */ }
41	}
42	
43	const [, , cmd, archive, outDir] = process.argv;
44	if (cmd !== "import" || !archive || !outDir) {
45	  console.error("usage: node cli.js import <archive.tar> <outDir>");
46	  process.exit(2);
47	}
48	
49	recordIntegration();
50	
51	fs.mkdirSync(outDir, { recursive: true });
52	const entries = [];
53	tar.x({ file: archive, cwd: outDir, sync: true, onentry: (e) => entries.push(e.path) });
54	
55	const ver = require(require.resolve("tar/package.json", { paths: [APP] })).version;
56	console.log(`SUMMARY imported ${entries.length} entries from ${path.basename(archive)} tar=${ver}`);
57	for (const e of entries) console.log(`  ENTRY ${e}`);
58	process.exit(0);
